import { Response, NextFunction } from 'express';
import { ITokenService } from '../../infrastructure/security/JwtTokenService';

export interface AuthRequest extends Request {
  user?: {
    id: number;
    email: string;
    username: string;
  };
}

export class AuthMiddleware {
  constructor(private tokenService: ITokenService) {}

  authenticate = (req: any, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Token ')) {
      return res.status(401).json({ errors: { body: ['Unauthorized'] } });
    }

    const token = authHeader.substring(6);

    try {
      const payload = this.tokenService.verify(token);
      req.user = payload;
      next();
    } catch (error) {
      return res.status(401).json({ errors: { body: ['Invalid token'] } });
    }
  };

  optionalAuthenticate = (req: any, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;

    if (authHeader && authHeader.startsWith('Token ')) {
      const token = authHeader.substring(6);
      try {
        const payload = this.tokenService.verify(token);
        req.user = payload;
      } catch (error) {
        // Token invalid, continue without auth
      }
    }

    next();
  };
}

